    bool result5 = idna::is_valid_domain(domain);
    bool result6 = idna::is_valid_label("testlabel");
    bool result7 = idna::is_ascii_domain(domain);
    bool result8 = idna::is_idn_domain(domain);
    std::string result9 = idna::to_lower("MIXEDCase");
    std::string result10 = idna::normalize(domain);
    std::string result11 = idna::extract_tld(domain);
    int result12 = idna::count_labels(domain);

    std::cout << result1 << std::endl;
